mapper.select:
SELECT 
  FROM TB_PAY P
 WHERE P.PAY_NO = #{payNo}

mapper.update:
UPDATE TB_PAY
   SET PAY_STAT = #{PAY_STAT}
     , UPD_DT   = SYSDATE
 WHERE PAY_NO   = #{PAY_NO}

UPDATE TB_PAY
   SET CNCL_AMT = CNCL_AMT + #{ADD_CNCL_AMT}
     , PAY_STAT = CASE WHEN PAY_AMT - (CNCL_AMT + #{ADD_CNCL_AMT}) <= 0 THEN 'C' ELSE 'P' END
     , UPD_DT   = SYSDATE
 WHERE PAY_NO   = #{PAY_NO}

UPDATE TB_PAY_CNCL
   SET CNCL_STAT   = #{CNCL_STAT}
     , RETRY_CNT   = RETRY_CNT + 1
     , PG_CNCL_TID = #{PG_CNCL_TID}
     , PG_RES_CD   = #{PG_RES_CD}
     , PG_RES_MSG  = SUBSTRB(#{PG_RES_MSG}, 1, 500)
 WHERE PAY_NO   = #{PAY_NO}
   AND CNCL_SEQ = #{CNCL_SEQ}
